INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Aravali Residence','the-aravali-residence','Indore, Madhya Pradesh','Residential','Full-service residential',2025,NULL,'','','','','A generous but disconnected plan needed to feel intimate without losing its sense of scale.','Walnut volumes, stone thresholds and a restrained lighting strategy establish a quiet sequence from public rooms to private spaces.','The Aravali Residence was conceived as a study in quiet continuity. Rather than filling the generous plan, the studio used proportion and material transitions to give each room a distinct role.\n\nWarm walnut anchors the joinery while natural stone carries light through the principal rooms. Bronze details are kept deliberately sparse, allowing the material palette to age rather than date.\n\nThe final home feels composed without feeling staged: practical circulation, generous storage and carefully calibrated light sit beneath a restrained visual language.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/aaadf1f6-e759-4637-8a6c-b056339a0a99.png',NULL,'','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,NULL,NULL,TRUE,'2026-09-27T14:07:21.303Z','2026-09-27T14:07:21.303Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Lake House','the-lake-house','Bhopal, Madhya Pradesh','Residential','Residential interiors',2024,NULL,'','','','','Frame the landscape without allowing the architecture to compete with it.','Warm plaster, deep timber and carefully placed openings create a softer relationship between the house and its setting.','The Lake House began with a simple architectural question: what should the interior do when the view is already the strongest element?\n\nThe answer was restraint. Deep timber, tactile plaster and a muted stone floor establish a grounded material vocabulary, while lighting is kept low and architectural after dusk.\n\nFurniture is deliberately sculptural but quiet, giving the landscape the final word.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/648c2d32-797a-4278-8627-df4a973b6da8.png',NULL,'','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,NULL,NULL,TRUE,'2026-09-27T14:07:21.303Z','2026-09-27T14:07:21.303Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Coastal Estate','the-coastal-estate','Goa, India','Residential','Residential',2026,4200,'Create a contemporary coastal residence that feels deeply connected to its setting without becoming a literal beach house. The brief called for an interior with architectural calm, tactile materials and enough flexibility for long family stays.','To make the horizon the quiet centre of the home. The interior is conceived as a sequence of softened thresholds, where white oak, limestone and woven fibres absorb the intensity of the coastal landscape rather than compete with it.','The challenge was less about fitting rooms into the footprint than establishing hierarchy. Circulation risked becoming a corridor around a very large living volume, while the ocean frontage demanded furniture and lighting decisions that would remain visually quiet from every angle.','The Crafted Solution','The plan needed to negotiate broad ocean-facing openings with intimate family zones, while controlling glare, salt exposure and the visual noise that can accumulate around a large open-plan footprint.','The studio developed a restrained material palette and used joinery as architecture. White oak millwork conceals storage and services, limestone establishes a continuous tactile floor plane, and curved furniture elements soften the geometry between the architecture and the landscape.','A contemporary coastal residence resolved through natural material, disciplined joinery and a deliberately quiet relationship with the sea.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/dc8098aa-f539-4438-9464-d0198a712091.png',NULL,'Modern organic luxury coastal living room with white oak millwork and limestone detailing.','[{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/dc8098aa-f539-4438-9464-d0198a712091.png","layout":"full-bleed","altText":"Modern organic luxury living room opening toward the sea with custom white oak millwork","caption":"The living room establishes the home’s material language through oak, limestone and linen."},{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/426d8446-3dcb-4100-adcf-e22051f7baf0.png","layout":"detail","altText":"Close editorial study of oak joinery, limestone and brushed bronze","caption":"A material study showing the precision of the joinery and tactile palette."}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'The Coastal Estate | Shri Sawariya Seth Interior Designs','A modern organic luxury coastal estate shaped by white oak, limestone, tactile textiles and restrained architectural detailing.',TRUE,'2026-09-27T14:30:45.795Z','2026-09-27T14:30:45.795Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Metropolitan Penthouse','the-metropolitan-penthouse','Mumbai, Maharashtra','Residential','Residential',2026,1850,'Transform a compact city penthouse into a highly resolved urban home with a sense of generosity, without adding visual bulk. The clients wanted strong architectural character, concealed storage and lighting that could shift from working day to evening entertaining.','To create density without clutter. The apartment is treated as a sequence of precise planes and shadows, using dark metal, pale timber and stone to frame rather than fill the available volume.','The principal spatial problem was compression. Conventional furniture groupings would have narrowed circulation, while a ceiling crowded with fixtures would have lowered the perceived height and diluted the architecture.','The Crafted Solution','The compact footprint demanded that every wall, junction and ceiling plane work harder. Services, storage and circulation competed for the same square metres, and the city outlook needed to remain legible without allowing the interior to feel dominated by glazing.','Custom steel fabrications establish fine structural lines, while integrated joinery absorbs storage, media and services. A layered architectural lighting scheme uses concealed linear sources, grazing light and focused pools to change the apartment’s atmosphere without changing its physical composition.','A compact metropolitan interior made generous through precision, concealment and architectural lighting rather than excess.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/3475e35c-806f-483c-9067-89333a1fa52f.png',NULL,'High-contrast urban minimalist penthouse with blackened steel, pale oak and architectural lighting.','[{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/3475e35c-806f-483c-9067-89333a1fa52f.png","layout":"full-bleed","altText":"High-contrast urban minimalist penthouse living room with custom steel and city view","caption":"A compact living volume disciplined by steel lines, stone and controlled light."},{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/426d8446-3dcb-4100-adcf-e22051f7baf0.png","layout":"detail","altText":"Luxury interior material detail with timber, stone and bronze craftsmanship","caption":"Material junctions are treated as architectural details rather than decoration."}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'The Metropolitan Penthouse | Shri Sawariya Seth Interior Designs','A high-contrast urban minimalist penthouse using custom steel, integrated joinery and layered architectural lighting to maximise a compact footprint.',TRUE,'2026-09-27T14:30:45.795Z','2026-09-27T14:30:45.795Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Heritage Manor','the-heritage-manor','Indore, Madhya Pradesh','Restoration','Residential',2025,3600,'Restore a historic manor without freezing it in the past. The owners wanted the original character respected, while the house gained contemporary comfort, discreet technology and a more coherent material story.','To allow old and new to coexist without either becoming theatrical. Original plaster, timber and proportion provide the structure; contemporary furniture, calibrated lighting and antique textiles supply the quieter layer of present-day life.','The spatial challenge was one of editing. Previous renovations had introduced competing finishes and visual interruptions. Restoring the hierarchy meant removing noise without erasing evidence of the building’s age.','The Crafted Solution','The existing plaster mouldings, uneven timberwork and accumulated interventions had to be retained where they carried architectural value, while new electrical, lighting, climate and media systems needed to disappear into the fabric of the building.','Original plaster mouldings were repaired rather than replaced, antique textiles were sourced for their irregular weave and patina, and modern smart-home controls were concealed within traditional joinery and switch locations. New interventions remain deliberately subordinate to the historic shell.','A historic manor carefully restored through subtraction, conservation and discreet contemporary intervention.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/69c1e6a1-5309-4eb0-8a31-90188e17d0b3.png',NULL,'Restored Indian heritage manor interior with original plaster moulding, antique textiles and contemporary furniture.','[{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/69c1e6a1-5309-4eb0-8a31-90188e17d0b3.png","layout":"full-bleed","altText":"Restored heritage manor living room with original plaster ceiling moulding and antique textile","caption":"Original architectural details remain legible against a restrained contemporary furnishing scheme."},{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/426d8446-3dcb-4100-adcf-e22051f7baf0.png","layout":"detail","altText":"Close study of tactile luxury materials and antique textile craftsmanship","caption":"Antique textiles introduce irregularity, age and a sense of collected history."}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'The Heritage Manor | Shri Sawariya Seth Interior Designs','A transitional heritage restoration preserving original plaster moulding while integrating discreet smart-home technology and antique textiles.',TRUE,'2026-09-27T14:30:45.795Z','2026-09-27T14:30:45.795Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Meridian House','the-meridian-house','Mumbai, Maharashtra','Commercial','Commercial interiors',2026,5200,'Create a refined hospitality environment that feels residential in its warmth but operates with the clarity and durability expected of a premium commercial space. The brief called for an interior with strong identity, discreet service infrastructure and a material palette capable of enduring intensive use.','The design treats hospitality as an exercise in atmosphere and sequence. Dark walnut, honed travertine and aged bronze establish a measured material hierarchy, while architectural lighting creates pools of intimacy within a larger open plan.','The large footprint risked becoming visually uniform. Service access, seating density, acoustic control and guest circulation needed to coexist without breaking the calm architectural language.','Custom walnut joinery conceals back-of-house requirements, while stone thresholds and bronze-framed partitions establish a clear rhythm between reception, lounge and private dining zones. Layered lighting keeps circulation legible while allowing guest areas to become progressively more intimate.','The large footprint risked becoming visually uniform. Service access, seating density, acoustic control and guest circulation needed to coexist without breaking the calm architectural language.','Custom walnut joinery conceals back-of-house requirements, while stone thresholds and bronze-framed partitions establish a clear rhythm between reception, lounge and private dining zones. Layered lighting keeps circulation legible while allowing guest areas to become progressively more intimate.','A premium commercial interior in Mumbai shaped by walnut, travertine, bronze and architectural lighting.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/c4c6b53f-9df4-435c-914a-b5075a4d3140.png',NULL,'Luxury boutique hospitality lounge in Mumbai with travertine, dark walnut and bronze detailing','[{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/c4c6b53f-9df4-435c-914a-b5075a4d3140.png","layout":"full-bleed","altText":"Luxury boutique hospitality lounge in Mumbai with travertine, dark walnut and bronze detailing","caption":"The Meridian House principal interior"}]'::jsonb,'[]'::jsonb,'["https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/c4c6b53f-9df4-435c-914a-b5075a4d3140.png"]'::jsonb,'[]'::jsonb,'The Meridian House | Shri Sawariya Seth Interior Designs','A premium commercial interior in Mumbai shaped by walnut, travertine, bronze and architectural lighting.',TRUE,'2026-09-27T14:59:39.780Z','2026-09-27T14:59:39.780Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Courtyard Residence','the-courtyard-residence','Bhopal, Madhya Pradesh','New Builds','New-build residential',2026,4600,'Develop the interior architecture for a newly constructed residence where every surface, opening and junction can be resolved as part of one coherent design language from the outset.','The vision was to create a residence that feels inevitable rather than decorated. Limestone, warm oak and carefully proportioned architectural openings create a quiet framework for daily life, with a central courtyard providing the visual and climatic anchor.','Because the project was conceived as a new build, the opportunity was also the constraint: architectural decisions, lighting, joinery, services and furniture needed to be coordinated before construction rather than corrected afterward.','The studio resolved joinery, lighting, stone transitions and furniture proportions alongside the architecture. A sculptural staircase becomes the vertical centrepiece, while concealed storage and integrated lighting preserve the clarity of the new-build envelope.','Because the project was conceived as a new build, the opportunity was also the constraint: architectural decisions, lighting, joinery, services and furniture needed to be coordinated before construction rather than corrected afterward.','The studio resolved joinery, lighting, stone transitions and furniture proportions alongside the architecture. A sculptural staircase becomes the vertical centrepiece, while concealed storage and integrated lighting preserve the clarity of the new-build envelope.','A contemporary new-build residence in Bhopal where architecture, lighting and interiors are resolved as one composition.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/4a9e175c-7c74-43f9-8328-b28d91a2952e.png',NULL,'Contemporary new-build residence in Bhopal with limestone, warm oak and sculptural staircase','[{"url":"https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/4a9e175c-7c74-43f9-8328-b28d91a2952e.png","layout":"full-bleed","altText":"Contemporary new-build residence in Bhopal with limestone, warm oak and sculptural staircase","caption":"The Courtyard Residence principal interior"}]'::jsonb,'[]'::jsonb,'["https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/4a9e175c-7c74-43f9-8328-b28d91a2952e.png"]'::jsonb,'[]'::jsonb,'The Courtyard Residence | Shri Sawariya Seth Interior Designs','A contemporary new-build residence in Bhopal where architecture, lighting and interiors are resolved as one composition.',TRUE,'2026-09-27T14:59:39.942Z','2026-09-27T14:59:39.942Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Dewas Residence','the-dewas-residence','Dewas, Madhya Pradesh','Residential','Full-service residential',2026,3200,'A family residence requiring a complete interior direction that respected its existing architecture while introducing contemporary storage, lighting and everyday functionality.','The vision was to make the house feel established rather than newly decorated, using proportion, material continuity and carefully edited furniture to give every room a sense of permanence.','The principal challenge was balancing the existing architectural rhythm with the practical demands of a contemporary family, particularly where circulation, concealed storage and electrical services intersected with original details.','Custom teak joinery, lime-finished surfaces, honed stone and antique textiles were coordinated as one material language. Lighting was recessed wherever possible, while visible fittings were selected as deliberate architectural details.','The residence had strong original proportions but lacked a coherent relationship between its formal rooms, daylight and contemporary family life.','The plan was reorganised around a quieter circulation spine, with teak joinery, lime plaster, natural stone and antique textiles establishing continuity without disguising the home’s regional character.','A restrained heritage-led residence in Dewas where original architectural character is paired with contemporary comfort. The palette moves through warm teak, pale stone and aged metal, allowing daylight and craft to carry the visual hierarchy.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/e9236422-85dd-476b-98c3-a917f21d76e4.png',NULL,'Dewas heritage residence with warm teak joinery, lime plaster and natural stone','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'The Dewas Residence | Shri Sawariya Seth Interior Designs','A refined heritage-led residential interior in Dewas, Madhya Pradesh, balancing original architectural character with contemporary family life.',TRUE,'2026-09-28T09:21:19.693Z','2026-09-28T09:21:19.693Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.projects (name,slug,location,project_type,category,year,square_footage,client_brief,vision,spatial_challenge,crafted_solution,challenge,solution,narrative,cover_image_url,hero_video_url,hero_alt_text,gallery_items,before_after_items,gallery_urls,video_urls,seo_title,seo_description,published,created_at,updated_at) VALUES ('The Ujjain Courtyard House','the-ujjain-courtyard-house','Ujjain, Madhya Pradesh','New Builds','New-build residential',2026,2800,'Create a contemporary family home with a strong sense of privacy, daylight and material calm despite a compact urban footprint.','The vision was to let the courtyard become the organising device, giving each principal room a visual relationship with greenery and allowing natural light to travel deeper into the plan.','The compact footprint made every transition consequential. The challenge was to avoid narrow corridors and visually fragmented rooms while maintaining acoustic and visual separation between public and private areas.','Local sandstone establishes the lower visual register, while pale oak and lime plaster soften the upper planes. Concealed storage keeps the rooms quiet, and layered architectural lighting extends the courtyard’s sense of depth after sunset.','A compact new-build plot required generous-feeling interiors without sacrificing privacy, natural light or the connection to an internal courtyard.','The design concentrates circulation along a central courtyard, using local sandstone, pale oak and lime plaster to create a continuous visual language from entrance to private rooms.','A modern organic residence in Ujjain shaped around a private courtyard. The architecture is quiet and tactile, with sandstone, pale oak and plaster creating a measured backdrop for sculptural furniture and filtered daylight.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/1e3667ba-7b34-4f2f-b307-068fb6410ab6.png',NULL,'Ujjain courtyard residence with local sandstone, pale oak and lime plaster','[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'[]'::jsonb,'The Ujjain Courtyard House | Shri Sawariya Seth Interior Designs','A modern organic courtyard residence in Ujjain, Madhya Pradesh, designed around privacy, daylight and tactile natural materials.',TRUE,'2026-09-28T09:21:19.693Z','2026-09-28T09:21:19.693Z') ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,location=EXCLUDED.location,project_type=EXCLUDED.project_type,category=EXCLUDED.category,year=EXCLUDED.year,square_footage=EXCLUDED.square_footage,client_brief=EXCLUDED.client_brief,vision=EXCLUDED.vision,spatial_challenge=EXCLUDED.spatial_challenge,crafted_solution=EXCLUDED.crafted_solution,challenge=EXCLUDED.challenge,solution=EXCLUDED.solution,narrative=EXCLUDED.narrative,cover_image_url=EXCLUDED.cover_image_url,hero_video_url=EXCLUDED.hero_video_url,hero_alt_text=EXCLUDED.hero_alt_text,gallery_items=EXCLUDED.gallery_items,before_after_items=EXCLUDED.before_after_items,gallery_urls=EXCLUDED.gallery_urls,video_urls=EXCLUDED.video_urls,seo_title=EXCLUDED.seo_title,seo_description=EXCLUDED.seo_description,published=EXCLUDED.published,updated_at=EXCLUDED.updated_at;
INSERT INTO public.journal_posts (title,slug,excerpt,body,cover_image_url,published,published_at,created_at,updated_at) VALUES ('How to Choose Interior Materials That Still Look Right Ten Years From Now','materials-that-age-well','Premium materials are not automatically timeless. The better question is how a surface responds to touch, sunlight, maintenance and the patina of daily life.','Premium materials are not automatically timeless. The better question is how a surface responds to touch, sunlight, maintenance and the patina of daily life. This note examines stone, timber, metal and textile choices through that longer lens.','https://f7e1eaf0-74c7-4c48-bd3a-7f925db03bf6.sandbox.floot.app/_cdn/static/2af2f21c-ec5f-4c06-8e8f-4bf594a09a9c.png',TRUE,'2026-09-27T14:11:32.054Z','2026-09-27T14:11:32.054Z','2026-09-27T14:11:32.054Z') ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title,excerpt=EXCLUDED.excerpt,body=EXCLUDED.body,cover_image_url=EXCLUDED.cover_image_url,published=EXCLUDED.published,published_at=EXCLUDED.published_at,updated_at=EXCLUDED.updated_at;
